esqlQuery.esql:
FROM logs-nginx.access.otel-*
// Proxied requests where NGINX connected to the backend, excluding stub_status checks
| WHERE nginx.upstream.response.duration IS NOT NULL AND nginx.upstream.connect.duration IS NOT NULL AND url.path != "/nginx_status"
// P95 upstream response time (seconds) and proxied request count per NGINX host
| STATS requests = COUNT(*), p95_upstream_s = PERCENTILE(nginx.upstream.response.duration, 95) BY host.name
// Minimum sample size to avoid noisy low-traffic hosts
| WHERE requests >= 20
| EVAL p95_upstream_s = ROUND(p95_upstream_s, 3)
// Alert threshold in seconds: adjust to your backend's expected response time
| WHERE p95_upstream_s > 1.0
| SORT p95_upstream_s DESC
| LIMIT 10
